/// The module waits by wait kind (nullptr: not a module wait, or one no op of the table sets).
namespace
{

/// @return the table
constexpr std::array<WaitPoll, kWaitCount> make_polls()
{
   std::array<WaitPoll, kWaitCount> polls{};
   polls[static_cast<int>(Wait::Bag)] = poll_bag;
   polls[static_cast<int>(Wait::Shop)] = poll_shop;
   polls[static_cast<int>(Wait::Mart)] = poll_mart;
   polls[static_cast<int>(Wait::Boxes)] = poll_boxes;
   polls[static_cast<int>(Wait::Transform)] = poll_transform;
   polls[static_cast<int>(Wait::Combine)] = poll_combine;
   polls[static_cast<int>(Wait::Nursery)] = poll_nursery;
   polls[static_cast<int>(Wait::Battle)] = poll_battle;
   polls[static_cast<int>(Wait::Approach)] = poll_approach;
   return polls;
}

}   // namespace

constinit const std::array<WaitPoll, kWaitCount> kModulePolls = make_polls();

